import math

N = 253036
divisors = []
for i in range(1, int(math.sqrt(N)) + 1):
    if N % i == 0:
        divisors.append(i)
        if i*i != N:
            divisors.append(N//i)
divisors.sort()

print(f"Found {len(divisors)} divisors of {N}")

S_min = 24
D_min = 3 * S_min + 503 # 72 + 503 = 575

solutions = []
for D in divisors:
    if D >= D_min:
        # Check D mod 3 == 2
        if D % 3 == 2:
            M = N // D
            # Check D + M - 1006 == 0 mod 9
            if (D + M - 1006) % 9 == 0:
                # If the conditions hold, k is an integer, and S is determined.
                S = (D - 503) / 3
                k = (D + M - 1006) / 9
                if S.is_integer() and k.is_integer() and S > 0 and k > 0:
                    solutions.append((S, k, D, M))

for sol in solutions:
    S, k, D, M = sol
    print(f"Found solution: S={S}, k={k}, D={D}, M={M}")

